css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .dish { position: absolute; inset: 0; border-radius: 50%; background: radial-gradient(circle at 40% 34%, color-mix(in srgb, var(--accent-2) 55%, transparent), color-mix(in srgb, var(--accent-2) 18%, transparent)); box-shadow: inset 0 0 0 3px color-mix(in srgb, var(--accent) 35%, transparent); }
.loader i { position: absolute; border-radius: 46% 54% 52% 48%; background: color-mix(in srgb, var(--accent) 78%, transparent); transform: scale(0); animation: petri-colony calc(var(--loader-speed) * 3.2) ease-out infinite; }
.loader i:nth-of-type(1) { left: 26%; top: 28%; width: 16%; height: 16%; }
.loader i:nth-of-type(2) { left: 54%; top: 22%; width: 12%; height: 12%; animation-delay: calc(var(--loader-speed) * .28); }
.loader i:nth-of-type(3) { left: 62%; top: 48%; width: 18%; height: 18%; animation-delay: calc(var(--loader-speed) * .56); }
.loader i:nth-of-type(4) { left: 34%; top: 58%; width: 14%; height: 14%; animation-delay: calc(var(--loader-speed) * .84); }
.loader i:nth-of-type(5) { left: 18%; top: 48%; width: 10%; height: 10%; animation-delay: calc(var(--loader-speed) * 1.12); }
.loader i:nth-of-type(6) { left: 48%; top: 68%; width: 11%; height: 11%; animation-delay: calc(var(--loader-speed) * 1.4); }
@keyframes petri-colony { 0%, 4% { transform: scale(0); opacity: 0; } 26%, 66% { transform: scale(1); opacity: 1; } 88%, 100% { transform: scale(1.15); opacity: 0; } }
